void main() {
  final fixture = _Fixture();

  setUp(() async {
    fixture.newRun();
    await fixture.pool.boot();
  });

  tearDown(fixture.disposeRun);

  _registerJobApiCoreTests(fixture);
  _registerJobApiKnobTests(fixture);
  _registerWorkerParityTests(fixture);
