      isolate.addOnExitListener(exitPort.sendPort, response: i);
      final port = await handshake.first as SendPort;
      handshake.close();
      _workers.add(
        _Worker(id: i, isolate: isolate, sendPort: port, doneBox: doneBox),
      );
    }
    _booted = true;
  }

