  ///
  /// Serving from cache makes a late `wait()` on an already-completed
  /// fire-and-forget job work. Waiting twice for the same job throws.
  AsyncJobEnvelope wait(int jobId) {
    final cached = _completed.remove(jobId);
    if (cached != null) {
      _jobs.remove(jobId);
