    AsyncWorkerMain? workerMain,
    this.workers = defaultWorkerCount,
    AsyncDispatchContext? dispatchContext,
    AsyncJobExecutor? executor,
  })  : assert(
          (workerMain == null) != (executor == null),
          'provide exactly one of workerMain / executor',
